import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {spawnSync} from 'node:child_process';
import {isDeepStrictEqual} from 'node:util';
import {sha256,publicEvidence} from '../../../scripts/eval/p2/artifacts.ts';
import {readJudgments,rescoreRun} from '../../../scripts/eval/p2/rescore.ts';
const base='story/testing/runs/P2R', review=base+'/P2R-JUDGE/20261031-j-r4-spotcheck-ai', destination=base+'/P2R-DECISIONS/20261031-d4-author-acceptance';
const read=p=>JSON.parse(readFileSync(p,'utf8')), summary=read(review+'/summary.json'), corrections=read(review+'/corrections.json'), sheet=read(review+'/author-spotcheck.json');
const git=(...args)=>{const r=spawnSync('git',['--no-optional-locks',...args],{encoding:'utf8',windowsHide:true});if(r.status!==0)throw Error('Git failed');return r.stdout.trim();};
const freeze=summary.sourceFreeze;
const drift=git('diff','--name-only',freeze,'--','.',':(exclude)story/testing/runs',':(exclude)story/testing/README.md');
if(drift)throw Error('Runtime source drift: '+drift);
if(summary.originalJudgmentFiles.length!==31||sheet.rows?.length!==176 && sheet.items?.length!==176)throw Error('Unexpected delivery shape');
const docs=summary.originalJudgmentFiles.map(f=>{const bytes=readFileSync(f.path);if(sha256(bytes)!==f.sha256)throw Error('Original judgment changed: '+f.path);const document=JSON.parse(bytes);if(document.sourceFreeze!==freeze||document.scores.length!==f.rows)throw Error('Wrong source/count');return{...f,document};});
const key=r=>[r.runId,r.metric,r.component,r.sampleId??r.itemId].join('\0');
let count=0,changes=0,errataRows=0;
const seen=new Set();
for(const d of docs){
 for(const row of d.document.scores){
  if(row.status!=='ai_preliminary'||row.pass!==row.final||row.sampleId!==row.itemId||seen.has(key(row)))throw Error('Unexpected original row');
  seen.add(key(row));count++;
  row.preApproval={status:row.status,pass:row.pass,final:row.final,note:row.note,judgmentStage:row.judgmentStage};
  for(const e of corrections.metricNoteErrata??[]){if(row.metric===e.metric&&row.component===e.component&&row.note===e.matchOriginalNote&&e.originalFiles.some(f=>f.path===d.path&&f.sha256===d.sha256)){row.note=e.correctedNote;errataRows++;}}
  const matches=corrections.items.filter(c=>key(c)===key(row));if(matches.length>1)throw Error('Duplicate correction');
  if(matches.length){const c=matches[0];if(c.originalFile!==d.path||c.originalFileSha256!==d.sha256||c.originalVerdict!==row.pass||c.originalNote!==row.preApproval.note)throw Error('Correction boundary mismatch');row.pass=c.correctedVerdict;row.final=c.correctedVerdict;row.note=c.correctedNote;row.correctionEvidence=destination+'/approval.json#corrections';changes+=Number(c.verdictChanged);}
  row.status='author_approved';row.judgmentStage='qualified_ai_judgment_author_accepted_delegate_review';row.authorPersonallyReviewed=false;
 }
 d.document.authorSpotcheckComplete=true;
 d.document.humanSpotcheckComplete=false;
 d.document.statusExplanation='作者明确认可AI代核及纠错，接受其作为本次抽查替代记录。author_approved表示作者认可结果，不表示本人逐项亲审；原判字段在preApproval和原交付提交中保留。';
 d.document.approval={evidence:destination+'/approval.json',mode:'author_accepted_ai_delegate',authorPersonallyReviewed:false};
}
if(count!==1715||changes!==4||errataRows!==36)throw Error('Wrong approval/correction count');
const effective=new Map();for(const d of docs)for(const r of d.document.scores){const k=r.metric+':'+r.component,v=effective.get(k)??{n:0,successes:0};v.n++;v.successes+=Number(r.pass);effective.set(k,v);}
const expected=summary.effectiveAiMetrics;
console.log(JSON.stringify({expectedShape:Array.isArray(expected)?expected[0]:expected,counts:Object.fromEntries(effective)},null,2));
for(const metric of expected)for(const [component,v] of Object.entries(metric.components)){if(!isDeepStrictEqual(effective.get(metric.metric+':'+component),{n:v.n,successes:v.successes}))throw Error('Effective count mismatch '+metric.metric+':'+component);}
const approval={schema:'story/p2r-author-judgment-approval@1',date:'2026-10-31',sourceFreeze:freeze,evidenceHead:git('rev-parse','HEAD'),authorReply:'认可 AI 代核及纠错结果',question:'D4交付为AI代核，是否认可其及纠错作为本次作者抽查替代记录？',mode:'author_accepted_ai_delegate',authorPersonallyReviewed:false,humanSpotcheckComplete:false,formalP2Passed:false,originalDeliveryCommit:summary.originalDeliveryCommit,originalJudgmentFiles:summary.originalJudgmentFiles,reviewSources:['summary.json','corrections.json','author-spotcheck.json','validation.json'].map(f=>({path:review+'/'+f,sha256:sha256(readFileSync(review+'/'+f))})),reviewed:176,acceptedRows:count,verdictChanges:changes,metricNoteErrataRows:errataRows,corrections:corrections.items,metricNoteErrata:corrections.metricNoteErrata,effectiveCounts:Object.fromEntries(effective),sourceEquivalence:{verified:true,excludedOnly:['story/testing/runs','story/testing/README.md'],differenceOutsideRuns:git('diff','--name-only',freeze,'--','.',':(exclude)story/testing/runs'),note:'J-R4交付增加测试入口README。代码、规则、评分器和其他配置与冻结相同；不还原他人文档，不声称当前全树等于冻结。'},notes:['原判保留在preApproval及7706c4e63交付提交。只变更新P2R判定和相应派生metrics，不动P2历史或原始raw。','作者认可不等于P2通过，所有失败、最少样本不足和缺失第二轮的null仍保留。']};
const json=x=>{const t=JSON.stringify(x,null,2)+'\n';publicEvidence(t);return t;};
// All source hashes, row identities and corrected counts have passed before mutation.
mkdirSync(destination,{recursive:true});writeFileSync(destination+'/approval.json',json(approval),{flag:'wx'});
const script=readFileSync(import.meta.filename,'utf8');writeFileSync(destination+'/reproduction.json',json({schema:'story/reproduction-source@1',scriptPath:'story/testing/exec/temp/p2r-accept-judgments.mjs',source:script,sourceSha256:sha256(script),instructions:'审核或重放应在原始交付判定状态进行；脚本先完整核对31份原文件哈希再写入，不能对已批准状态重复执行。'}),{flag:'wx'});
for(const d of docs)writeFileSync(d.path,json(d.document));
const folders=[...new Set(docs.map(d=>d.path.split('/judgments/')[0]))];
for(const folder of folders){const rows=readJudgments(folder);if(rows.some(r=>r.status!=='author_approved'))throw Error('Not approved');rescoreRun(folder,true);if(!rescoreRun(folder).equal)throw Error('Rescore unstable');}
console.log(JSON.stringify({approvedRows:count,changedVerdicts:changes,errataRows,runFolders:folders,approval:destination+'/approval.json'}));
